# Try the correct LCF notation for the McGee graph
# [12, 7, -7, 7, -7, -12, 7, -7, 7, -7, 12, 7, -7, 7, -7, -12, 7, -7, 7, -7, 12, 7, -7, 7]

lcf = [12, 7, -7, 7, -7, -12, 7, -7, 7, -7, 12, 7, -7, 7, -7, -12, 7, -7, 7, -7, 12, 7, -7, 7]
print(len(lcf))

n = 24
edges = set()

# Add cycle edges
for i in range(n):
    u = i
    v = (i + 1) % n
    if u < v:
        edges.add((u, v))
    else:
        edges.add((v, u))

# Add LCF edges
for i in range(n):
    u = i
    v = (i + lcf[i]) % n
    if u < v:
        edges.add((u, v))
    else:
        edges.add((v, u))

print(f"Number of edges: {len(edges)}")
print("Edges:", sorted(edges))

# Check girth
def shortest_cycle(edges, n):
    adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    min_cycle = n + 1

    for start in range(n):
        dist = [-1] * n
        parent = [-1] * n
        dist[start] = 0
        queue = [start]

        for u in queue:
            for v in adj[u]:
                if dist[v] == -1:
                    dist[v] = dist[u] + 1
                    parent[v] = u
                    queue.append(v)
                elif v != parent[u]:
                    cycle_len = dist[u] + dist[v] + 1
                    if cycle_len < min_cycle:
                        min_cycle = cycle_len

    return min_cycle

girth = shortest_cycle(edges, n)
print(f"Girth: {girth}")

# Check 4-colorability
def is_colorable(edges, n, max_colors):
    adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    colors = [-1] * n

    def backtrack(v):
        if v == n:
            return True
        used = set()
        for nb in adj[v]:
            if colors[nb] != -1:
                used.add(colors[nb])
        for c in range(max_colors):
            if c not in used:
                colors[v] = c
                if backtrack(v + 1):
                    return True
                colors[v] = -1
        return False

    if backtrack(0):
        return True, colors
    return False, None

ok, colors = is_colorable(edges, n, 4)
print(f"4-colorable: {ok}")
if ok:
    print(f"Colors: {colors}")
